// Space_Invaders/SpaceInvadersGame.js
// The orchestrator: owns the state machine (menu / playing / paused /
// waveclear / gameover), drives every entity + system each frame, and routes
// gameplay events into the shared VFX / audio / UI layers.
//
// It does NOT own the renderer or the shared services — those are injected
// so the same game can run under any Engine. All per-frame work is
// allocation-free (pools + scratch vectors).

import * as THREE from 'three';
import { CONFIG } from './config.js';
import { clamp, randRange } from '../shared/utils/Math.js';
import { makeGridTexture } from '../shared/utils/Procedural.js';
import Player from './entities/Player.js';
import { InvaderFormation } from './entities/InvaderFormation.js';
import Bullet from './entities/Bullet.js';
import InvaderBullet from './entities/InvaderBullet.js';
import BonusInvader from './entities/BonusInvader.js';
import Shield from './entities/Shield.js';
import Starfield from './entities/Starfield.js';
import { bulletHitsInvader, bulletHitsBlock, circleCircle } from './systems/CollisionSystem.js';
import { ScoreSystem } from './systems/ScoreSystem.js';
import SpawnerSystem from './systems/SpawnerSystem.js';
import ObjectPool from '../shared/core/ObjectPool.js';

export default class SpaceInvadersGame {
  /**
   * @param {object} ctx
   *   engine, input, timescale, audio, music, ui,
   *   particles, rings, trails, text, shake
   */
  constructor(ctx) {
    this.ctx = ctx;
    this.engine = ctx.engine;
    this.input = ctx.input;
    this.audio = ctx.audio;
    this.music = ctx.music;
    this.ui = ctx.ui;
    this.particles = ctx.particles;
    this.rings = ctx.rings;
    this.trails = ctx.trails;
    this.text = ctx.text;
    this.shake = ctx.shake;

    this.state = 'menu';
    this.wave = 1;
    this.score = 0;
    this.lives = CONFIG.scoring.startLives;
    this._waveClearTimer = 0;
    this._marchStep = 0;

    // Scratch (no per-frame allocation).
    this._v = new THREE.Vector3();

    this._buildWorld();
    this._wireUI();
  }

  // ------------------------------------------------------------- world build

  _buildWorld() {
    const { engine } = this.ctx;
    const C = CONFIG;

    this.starfield = new Starfield(engine.scene, { count: 900 });

    // Lights: a cool key + a magenta rim so the PBR invaders read with depth.
    const key = new THREE.DirectionalLight(0xbfe8ff, 1.1);
    key.position.set(4, 8, 10);
    engine.scene.add(key);
    const rim = new THREE.DirectionalLight(0xff2fd6, 0.5);
    rim.position.set(-6, -4, 6);
    engine.scene.add(rim);
    engine.scene.add(new THREE.AmbientLight(0x223344, 0.7));

    this.player = new Player(engine.scene, C);
    this.formation = new InvaderFormation(engine, C);
    this.shields = new Shield(engine.scene, C);

    this.bulletPool = new ObjectPool(() => new Bullet(engine.scene, C), C.bullet.poolSize);
    this.invaderBulletPool = new ObjectPool(() => new InvaderBullet(engine.scene, C), C.invaderBullet.poolSize);
    // Stable ids for trail keys.
    this.bulletPool.items.forEach((b, i) => { b.id = i; });
    this.invaderBulletPool.items.forEach((b, i) => { b.id = i; });

    this.bonus = new BonusInvader(engine.scene, C);

    this.scoreSys = new ScoreSystem();
    this.spawner = new SpawnerSystem();

    // A faint neon floor grid anchors the playfield in space.
    this._buildFloor();
  }

  _buildFloor() {
    const { engine } = this.ctx;
    const tex = makeGridTexture(512, 16, '#00e5ff', '#070714');
    tex.repeat.set(6, 4);
    const geo = new THREE.PlaneGeometry(40, 26);
    const mat = new THREE.MeshStandardMaterial({
      color: 0x0a0f1e,
      emissive: 0x0a2a33,
      emissiveIntensity: 0.35,
      roughness: 0.85,
      metalness: 0.1,
      map: tex,
      emissiveMap: tex,
      transparent: true,
      opacity: 0.5,
    });
    const floor = new THREE.Mesh(geo, mat);
    floor.rotation.x = -Math.PI / 2;
    floor.position.set(0, -9.2, -2);
    engine.scene.add(floor);
    this._floor = floor;
  }

  // ------------------------------------------------------------- UI wiring

  _wireUI() {
    this.ui.onPrimary = () => this._onPrimary();
    this.ui.onSecondary = () => this._onSecondary();
    this._showMenu();
  }

  _showMenu() {
    this.state = 'menu';
    this.ui.showHud();
    this.ui.setHudSlot('score', '0');
    this.ui.setHudSlot('wave', '1');
    this.ui.setHudSlot('lives', String(this.lives));
    this.ui.setCombo(1);
    this.ui.showScreen('menu', {
      title: 'NEON INVADERS',
      sub: 'retro-futurism · wave 1',
      lines: [
        'Move — WASD / Arrows / Left Stick',
        'Fire — Space / J / A / X / RT',
        'Pause — P / Esc / Start',
        'Clear the formation. Survive the descent.',
      ],
      primary: 'Launch',
    });
  }

  _onPrimary() {
    this.audio.init(); // user gesture → unlock audio
    this.audio.uiSelect();
    if (this.state === 'menu' || this.state === 'gameover') {
      this.startGame();
    } else if (this.state === 'paused') {
      this._resume();
    }
  }

  _onSecondary() {
    this.audio.init();
    this.audio.setMuted(!this.audio.muted);
  }

  // ------------------------------------------------------------- game flow

  startGame() {
    this.wave = 1;
    this.score = 0;
    this.lives = CONFIG.scoring.startLives;
    this.scoreSys.reset();
    this.spawner.reset();
    this._startWave();
  }

  _startWave() {
    this.formation.reset(this.wave);
    this.shields.reset();
    this.player.respawn();
    this.bulletPool.releaseAll();
    this.invaderBulletPool.releaseAll();
    this.bonus.deactivate();
    this.particles.clear();
    this.rings.clear();
    this.trails.clear();
    this.text.clear();
    this.shake.reset();
    this.ctx.timescale.set(1.0);

    this._syncHud();
    this.ui.hideScreen();
    this.state = 'playing';

    // Music: intensity scales with the wave.
    this.music.setTrack(this._trackForWave(this.wave));
    this.music.setIntensity(clamp(0.35 + this.wave * 0.12, 0, 0.95));
    this.music.start();
  }

  _trackForWave(wave) {
    // A minor-ish progression, one step up per wave for tension.
    const root = 45 + Math.min(wave - 1, 6); // A2 → up
    const bass = [root, 0, root, 0, root + 5, 0, root + 3, 0];
    const arp = [root + 12, root + 15, root + 17, root + 19, root + 22, root + 19, root + 17, root + 15];
    return {
      bpm: 112 + Math.min(wave, 8) * 4,
      bass,
      arp,
      hat: [1, 0, 1, 0, 1, 1, 0, 1],
      bassWave: 'sawtooth',
      bassCutoff: 300 + wave * 40,
    };
  }

  _pause() {
    if (this.state !== 'playing') return;
    this.state = 'paused';
    this.music.stop();
    this.ui.showScreen('pause', {
      title: 'PAUSED',
      sub: 'systems on standby',
      lines: ['Score — ' + this.score, 'Wave — ' + this.wave],
      primary: 'Resume',
      secondary: 'Mute',
    });
  }

  _resume() {
    if (this.state !== 'paused') return;
    this.state = 'playing';
    this.ui.hideScreen();
    this.music.start();
  }

  _gameOver(reason) {
    this.state = 'gameover';
    this.music.stop();
    this.audio.gameOver();
    this.shake.add(0.9);
    this.ui.showScreen('gameover', {
      title: reason === 'invasion' ? 'INVADED' : 'DESTROYED',
      sub: reason === 'invasion' ? 'the fleet reached the surface' : 'cannon offline',
      lines: [
        'Final Score — ' + this.score,
        'Waves Cleared — ' + (this.wave - 1),
      ],
      primary: 'Re-Launch',
      secondary: 'Mute',
    });
  }

  _waveCleared() {
    this.state = 'waveclear';
    this._waveClearTimer = 2.4;
    this.audio.waveClear();
    this.music.setIntensity(1.0);
    // Celebratory burst across the field.
    for (let i = 0; i < 3; i++) {
      this.particles.burst(this._v.set(randRange(-6, 6), randRange(0, 4), 0), {
        count: 40, speed: [3, 9], life: [0.5, 1.1],
        color: [0x00f0ff, 0xff2fd6, 0xffc857], gravity: 2,
      });
    }
  }

  // ------------------------------------------------------------- per-frame

  /** Called by the Engine each frame. dt = scaled, raw = real seconds. */
  update(dt, raw) {
    this.input.sample();

    // Global pause toggle (works from playing or paused).
    if (this.input.pressedAction('pause')) {
      if (this.state === 'playing') this._pause();
      else if (this.state === 'paused') this._resume();
    }

    // Menu / game-over: gamepad or keyboard "start" launches.
    if ((this.state === 'menu' || this.state === 'gameover') && this.input.pressedAction('start')) {
      this._onPrimary();
    }

    // Camera shake always runs on real time so hit-stop doesn't smear it.
    this.shake.update(raw);

    switch (this.state) {
      case 'menu':
        this._updateAmbient(dt);
        break;
      case 'playing':
        this._updatePlaying(dt);
        break;
      case 'waveclear':
        this._updateAmbient(dt);
        this._waveClearTimer -= raw;
        if (this._waveClearTimer <= 0) {
          this.wave++;
          this.spawner.nextWave();
          this._startWave();
        }
        break;
      case 'paused':
      case 'gameover':
        break;
    }

    // Shared VFX that run in every live state.
    this.particles.update(dt, this.engine.camera);
    this.rings.update(raw);
    this.trails.update(raw);
    this.text.update(raw, this.engine.camera, this.engine.width, this.engine.height);

    this.input.endFrame();
  }

  _updateAmbient(dt) {
    this.starfield.update(dt);
    this.formation.update(dt);
    this.player.update(dt, 0);
  }

  _updatePlaying(dt) {
    const C = CONFIG;
    this.starfield.update(dt);

    // --- Player ---
    const axis = this.input.axis('x');
    this.player.update(dt, axis);

    // --- Fire (classic: one live bullet) ---
    if (this.input.down('fire') && this.player.canFire() && this.bulletPool.activeCount < C.player.maxBullets) {
      const b = this.bulletPool.acquire();
      if (b) {
        b.spawn(this.player.x, this.player.y + 0.6);
        this.audio.laser();
        this.trails.track('pb' + b.id, b.x, b.y, 0);
      }
    }

    // --- Formation (steps + descent) ---
    const steps = this.formation.update(dt);
    for (let s = 0; s < steps; s++) {
      this._marchStep = (this._marchStep + 1) & 3;
      this.audio.march(this._marchStep);
    }

    // --- Invader fire (rate-based, bottom-of-column shooters) ---
    this._invaderFire(dt);

    // --- Move projectiles ---
    this.bulletPool.forEachActive((b) => {
      b.update(dt);
      this.trails.track('pb' + b.id, b.x, b.y, 0);
    });
    this.invaderBulletPool.forEachActive((b) => {
      b.update(dt);
      this.trails.track('ib' + b.id, b.x, b.y, 0);
    });

    // --- Bonus invader ---
    if (this.bonus.active) {
      this.bonus.update(dt);
      this.trails.track('bonus', this.bonus.x, this.bonus.y, 0);
    }

    // --- Collisions ---
    this._resolveCollisions();

    // --- Score / combo decay ---
    this.scoreSys.update(dt);
    this._syncHud();

    // --- Win / loss ---
    if (this.formation.aliveCount === 0) {
      this._waveCleared();
      return;
    }
    if (this.formation.hasInvaded(this.player.y)) {
      this._gameOver('invasion');
      return;
    }
  }

  // ------------------------------------------------------------- invader fire

  _invaderFire(dt) {
    const C = CONFIG;
    const alive = this.formation.aliveCount;
    if (alive === 0) return;
    const rate = (C.invaderBullet.baseRate + C.invaderBullet.ratePerMissing * (C.invader.cols * C.invader.rows - alive))
      * this.spawner.waveParams().fireRateScale;
    const maxConc = alive < 12 ? C.invaderBullet.maxConcurrentLate : C.invaderBullet.maxConcurrent;
    if (this.invaderBulletPool.activeCount >= maxConc) return;
    if (Math.random() > rate * dt) return;

    // Pick a random column that still has a live invader; fire from its lowest.
    const col = (Math.random() * C.invader.cols) | 0;
    const shooter = this.formation.bottomShooter(col);
    if (!shooter) return;
    const b = this.invaderBulletPool.acquire();
    if (!b) return;
    const wp = this.formation.worldPos(shooter);
    b.spawn(wp.x, wp.y - 0.4);
  }

  // ------------------------------------------------------------- collisions

  _resolveCollisions() {
    const C = CONFIG;
    const F = this.formation;
    const P = this.player;

    // Player bullets vs invaders (swept).
    this.bulletPool.forEachActive((b) => {
      if (!b.active) return;
      let hit = null;
      F.forEachAlive((inv) => {
        if (hit) return;
        if (bulletHitsInvader(b, { x: inv.x, y: inv.y, radius: F.radius })) hit = inv;
      });
      if (hit) {
        b.kill();
        this._onInvaderKilled(hit);
        return;
      }
      // vs bonus
      if (this.bonus.active && bulletHitsInvader(b, { x: this.bonus.x, y: this.bonus.y, radius: this.bonus.radius })) {
        b.kill();
        this._onBonusKilled();
        return;
      }
      // vs shields (swept vs AABB — no tunneling at 38 m/s)
      for (const block of this.shields.blocks) {
        if (!block.alive) continue;
        if (bulletHitsBlock(b, { x: block.cx, y: this.shields.y, w: block.w, h: block.h })) {
          b.kill();
          this._onShieldHit(block, b.x, b.y);
          break;
        }
      }
    });

    // Invader bullets vs shields, then vs player.
    this.invaderBulletPool.forEachActive((b) => {
      if (!b.active) return;
      const sh = this.shields.hitByPoint(b.x, b.y);
      if (sh) {
        b.kill();
        this._onShieldHit(sh, b.x, b.y);
        return;
      }
      if (P.alive && !P.invulnerable
        && circleCircle(b.x, b.y, C.invaderBullet.radius, P.x, P.y, P.radius)) {
        b.kill();
        this._onPlayerHit();
      }
    });

    // Invaders vs shields (descent erodes the barrier).
    F.forEachAlive((inv) => {
      const sh = this.shields.hitByPoint(inv.x, inv.y);
      if (sh !== -1) this._onShieldHit(sh, inv.x, inv.y, true);
    });

    // Invaders vs player (invasion contact).
    if (P.alive && !P.invulnerable) {
      const contact = F.firstContact(P.x, P.y, P.radius + F.radius);
      if (contact) this._onPlayerHit();
    }
  }

  // ------------------------------------------------------------- event handlers

  _onInvaderKilled(inv) {
    const C = CONFIG;
    this.formation.killAt(inv.col, inv.row);

    const base = C.invader.pointsBySpecies[inv.species];
    const awarded = this.scoreSys.addKill(base);
    this.score += awarded;
    const mult = this.scoreSys.multiplier;

    // VFX priority: hit-stop → shake → particles → ring → text.
    this.ctx.timescale.freeze(0.35, 45);
    this.shake.add(0.25);
    this.particles.burst(this._v.set(inv.x, inv.y, 0), {
      count: 26, speed: [2, 8], life: [0.3, 0.8],
      color: C.invader.colorBySpecies[inv.species], gravity: 3, drag: 1.5,
    });
    this.rings.spawn(this._v.set(inv.x, inv.y, 0), 1.6, 0.4, C.invader.colorBySpecies[inv.species]);
    this.text.spawn(inv.x, inv.y + 0.4, 0, `+${awarded}`, {
      color: '#' + C.invader.colorBySpecies[inv.species].toString(16).padStart(6, '0'),
      size: mult > 1 ? 18 : 15,
    });
    if (mult > 1) this.text.spawn(inv.x, inv.y + 0.9, 0, `×${mult} COMBO`, { color: '#ffc857', size: 12, life: 0.7 });

    this.audio.invaderKill();

    // 1UP check.
    if (this.scoreSys.consumeOneUp()) {
      this.lives++;
      this.audio.oneUp();
      this.text.spawn(this.player.x, this.player.y + 1.2, 0, '1UP', { color: '#57ff9a', size: 22, life: 1.2 });
    }

    // Bonus invader cadence.
    if (this.spawner.registerKill() && !this.bonus.active) {
      this.bonus.activate();
      this.audio.bonusSpawn();
    }
  }

  _onBonusKilled() {
    const C = CONFIG;
    const pts = C.bonus.points;
    this.score += pts;
    this.bonus.deactivate();
    this.spawner.bonusKilled();
    this.ctx.timescale.freeze(0.3, 50);
    this.shake.add(0.35);
    this.particles.burst(this._v.set(this.bonus.x, this.bonus.y, 0), {
      count: 40, speed: [3, 10], life: [0.4, 0.9],
      color: [C.bonus.color, 0xffffff], gravity: 2,
    });
    this.rings.spawn(this._v.set(this.bonus.x, this.bonus.y, 0), 2.2, 0.5, C.bonus.color);
    this.text.spawn(this.bonus.x, this.bonus.y + 0.5, 0, `BONUS +${pts}`, { color: '#ffc857', size: 18 });
    this.audio.bonusKill();
  }

  _onShieldHit(blockIndex, x, y, fromInvader = false) {
    const C = CONFIG;
    const destroyed = this.shields.damage(blockIndex, x, y);
    this.shake.add(fromInvader ? 0.12 : 0.08);
    this.particles.burst(this._v.set(x, y, 0), {
      count: fromInvader ? 14 : 8, speed: [1, 4], life: [0.2, 0.5],
      color: C.shield.color, gravity: 4,
    });
    if (destroyed) {
      this.rings.spawn(this._v.set(x, y, 0), 1.2, 0.35, C.shield.color);
      this.audio.shieldHit();
    }
  }

  _onPlayerHit() {
    this.lives--;
    this.scoreSys.loseLife();

    // P0 hit-stop (strong), P1 shake (strong), P2 big burst, P3 big ring.
    this.ctx.timescale.freeze(0.05, 90);
    this.shake.add(0.85);
    this.particles.burst(this._v.set(this.player.x, this.player.y, 0), {
      count: 60, speed: [3, 12], life: [0.4, 1.0],
      color: [0x00f0ff, 0xffffff, 0xff2fd6], gravity: 2,
    });
    this.rings.spawn(this._v.set(this.player.x, this.player.y, 0), 3.0, 0.6, 0x00f0ff);
    this.text.spawn(this.player.x, this.player.y + 1.0, 0, 'HIT', { color: '#ff2fd6', size: 20 });
    this.audio.playerHit();

    // Clear any invader bullets near the player so the respawn is fair.
    this.invaderBulletPool.forEachActive((b) => {
      if (Math.abs(b.x - this.player.x) < 3 && b.y < this.player.y + 2) b.kill();
    });

    if (this.lives < 0) {
      this.player.alive = false;
      this._gameOver('destroyed');
    } else {
      this.player.respawn();
    }
  }

  // ------------------------------------------------------------- HUD

  _syncHud() {
    this.ui.setHudSlot('score', String(this.score));
    this.ui.setHudSlot('wave', String(this.wave));
    this.ui.setHudSlot('lives', String(Math.max(0, this.lives)));
    this.ui.setCombo(this.scoreSys.multiplier);
  }

  // ------------------------------------------------------------- teardown

  onResize() {
    // Nothing to do: FloatingText reads engine.width/height each frame.
  }

  dispose() {
    this.music.dispose();
    this.starfield.dispose();
    this.player.dispose();
    this.formation.dispose();
    this.shields.dispose();
    this.bonus.dispose();
    this.bulletPool.items.forEach((b) => b.dispose());
    this.invaderBulletPool.items.forEach((b) => b.dispose());
    if (this._floor) {
      this._floor.geometry.dispose();
      this._floor.material.dispose();
      if (this._floor.material.map) this._floor.material.map.dispose();
    }
  }
}

/**
 * ObjectPool — pre-allocated, zero-allocation acquire/release.
 *
 * Usage:
 *   const pool = new ObjectPool(() => new Bullet(), 8);
 *   const b = pool.acquire();      // null when exhausted
 *   ...
 *   pool.release(b);               // idempotent
 *   pool.forEachActive(fn);        // fn(item) over live items
 *   pool.releaseAll();
 *
 * Contract: `release` is safe to call twice on the same item.
 */
export default class ObjectPool {
  constructor(factory, size) {
    this.factory = factory;
    this.items = [];
    this.active = [];
    for (let i = 0; i < size; i++) this.items.push(factory());
  }

  get freeCount() { return this.items.length; }
  get activeCount() { return this.active.length; }

  acquire() {
    if (this.items.length === 0) return null;
    const item = this.items.pop();
    this.active.push(item);
    return item;
  }

  release(item) {
    const i = this.active.indexOf(item);
    if (i === -1) return; // already released
    this.active.splice(i, 1);
    this.items.push(item);
  }

  releaseAll() {
    while (this.active.length > 0) this.items.push(this.active.pop());
  }

  forEachActive(fn) {
    for (let i = 0; i < this.active.length; i++) fn(this.active[i]);
  }

  /** Remove items for which predicate(item) === true (caller keeps ownership). */
  removeWhere(predicate) {
    const removed = [];
    for (let i = this.active.length - 1; i >= 0; i--) {
      if (predicate(this.active[i])) {
        removed.push(this.active.splice(i, 1)[0]);
        this.items.push(removed[removed.length - 1]);
      }
    }
    return removed;
  }
}

import * as THREE from 'three';

/**
 * Engine — renderer, scene, camera, clock, clamped-delta loop, resize,
 * and a full recursive dispose() that walks the scene graph and releases
 * every geometry, material, and texture.
 *
 * The game supplies an `update(dt)` callback (dt already scaled by
 * TimeScale and clamped) and an optional `render()` hook.
 */
export class Engine {
  constructor({ canvas, width, height, background = 0x050510, exposure = 1.1, anisotropy = 4, timescale = null } = {}) {
    this.width = width;
    this.height = height;

    this.renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.setSize(width, height, false);
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = exposure;

    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(background);
    this.scene.fog = new THREE.FogExp2(background, 0.012);

    this.camera = new THREE.PerspectiveCamera(50, width / height, 0.1, 200);
    this.camera.position.set(0, 0, 26);
    this.camera.lookAt(0, 0, 0);

    this.clock = new THREE.Clock();
    this.timescale = timescale; // TimeScale instance; dt is scaled by its .value
    this.running = false;
    this._raf = 0;
    this._update = null;
    this._renderHook = null;
    this._maxDelta = 1 / 30;
    this._disposed = false;
    this.anisotropy = anisotropy;
    /** Objects with a dispose() the engine should call on teardown (e.g. Composer). */
    this.disposables = [];
  }

  /** Register an object to dispose when the engine disposes. */
  addDisposable(obj) { this.disposables.push(obj); return obj; }

  /** Register the per-frame update callback: update(dt) where dt is scaled+clamped. */
  onUpdate(fn) { this._update = fn; }
  /** Optional hook called after update, before render (e.g. composer setup). */
  onRender(fn) { this._renderHook = fn; }

  start() {
    if (this.running) return;
    this.running = true;
    this.clock.start();
    const loop = () => {
      if (!this.running) return;
      this._raf = requestAnimationFrame(loop);
      const raw = Math.min(this.clock.getDelta(), this._maxDelta);
      if (this.timescale) this.timescale.update(raw);
      const dt = raw * (this.timescale ? this.timescale.value : 1);
      if (this._update) this._update(dt, raw);
      // A render hook (e.g. EffectComposer) takes over presentation;
      // otherwise fall back to a plain render.
      if (this._renderHook) this._renderHook();
      else this.renderer.render(this.scene, this.camera);
    };
    this._raf = requestAnimationFrame(loop);
  }

  stop() {
    this.running = false;
    if (this._raf) cancelAnimationFrame(this._raf);
    this._raf = 0;
  }

  resize(width, height) {
    this.width = width;
    this.height = height;
    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
  }

  /**
   * Dispose everything: renderer, scene graph (geometries, materials,
   * textures), and stop the loop. Safe to call multiple times.
   */
  dispose() {
    if (this._disposed) return;
    this._disposed = true;
    this.stop();
    this._walkAndDispose(this.scene);
    for (const d of this.disposables) { try { d.dispose(); } catch (e) { /* already disposed */ } }
    this.disposables.length = 0;
    this.scene.background = null;
    this.scene.fog = null;
    this.renderer.dispose();
  }

  _walkAndDispose(root) {
    const queue = [root];
    const seenMaterials = new Set();
    const seenGeometries = new Set();
    const seenTextures = new Set();
    while (queue.length) {
      const obj = queue.shift();
      if (obj.children) for (const c of obj.children) queue.push(c);
      if (obj.geometry && !seenGeometries.has(obj.geometry)) {
        seenGeometries.add(obj.geometry);
        obj.geometry.dispose();
      }
      const mats = obj.material ? (Array.isArray(obj.material) ? obj.material : [obj.material]) : [];
      for (const m of mats) {
        if (!m || seenMaterials.has(m)) continue;
        seenMaterials.add(m);
        for (const key of Object.keys(m)) {
          const v = m[key];
          if (v && v.isTexture && !seenTextures.has(v)) {
            seenTextures.add(v);
            v.dispose();
          }
        }
        m.dispose();
      }
    }
  }
}

// Unified dual-input controller: Keyboard (WASD / arrows) + Gamepad API.
// Exposes one normalized query API regardless of source. No per-frame
// allocation: key state is a fixed Set, gamepad samples are cached in
// module-level scratch objects.

const AXIS_KEYS = {
  left: ['KeyA', 'ArrowLeft'],
  right: ['KeyD', 'ArrowRight'],
  up: ['KeyW', 'ArrowUp'],
  down: ['KeyS', 'ArrowDown'],
};

const ACTION_KEYS = {
  fire: ['Space', 'KeyJ'],
  pause: ['KeyP', 'Escape'],
  start: ['Enter', 'Space'],
};

const DEADZONE = 0.22;

function deadzone(v) {
  if (Math.abs(v) < DEADZONE) return 0;
  return (v - Math.sign(v) * DEADZONE) / (1 - DEADZONE);
}

export default class Input {
  constructor() {
    this.keys = new Set();
    this.pressed = new Set(); // edge-triggered, drained each frame
    this.released = new Set();
    this._padPressed = new Set(); // gamepad buttons pressed since last sample
    this.gamepadIndex = null;
    this.gamepadConnected = false;
    this._padButtons = [];
    this._padAxes = [0, 0, 0, 0];
    this._boundKeyDown = this._onKeyDown.bind(this);
    this._boundKeyUp = this._onKeyUp.bind(this);
    this._boundBlur = this._onBlur.bind(this);
    this._boundPad = this._onPad.bind(this);
    window.addEventListener('keydown', this._boundKeyDown, { passive: true });
    window.addEventListener('keyup', this._boundKeyUp, { passive: true });
    window.addEventListener('blur', this._boundBlur);
    window.addEventListener('gamepadconnected', this._boundPad);
    window.addEventListener('gamepaddisconnected', this._boundPad);
  }

  _onKeyDown(e) {
    if (e.repeat) return;
    this.keys.add(e.code);
    this.pressed.add(e.code);
    // Keep the page from scrolling on game keys.
    if (e.code === 'Space' || e.code.startsWith('Arrow')) e.preventDefault();
  }

  _onKeyUp(e) {
    this.keys.delete(e.code);
    this.released.add(e.code);
  }

  _onBlur() {
    this.keys.clear();
    this.pressed.clear();
    this.released.clear();
  }

  _onPad() {
    const pads = navigator.getGamepads ? navigator.getGamepads() : [];
    for (const p of pads) {
      if (p && p.connected) {
        this.gamepadIndex = p.index;
        this.gamepadConnected = true;
        return;
      }
    }
    this.gamepadIndex = null;
    this.gamepadConnected = false;
  }

  /**
   * Sample gamepad state once per frame (call before reading axes/buttons).
   * Gamepad API state is only valid during the rAF callback window.
   */
  sample() {
    if (this.gamepadIndex === null) {
      this._padButtons.length = 0;
      return;
    }
    const pad = navigator.getGamepads ? navigator.getGamepads()[this.gamepadIndex] : null;
    if (!pad || !pad.connected) {
      this._padButtons.length = 0;
      return;
    }
    const prev = this._padButtons;
    this._padButtons.length = pad.buttons.length;
    for (let i = 0; i < pad.buttons.length; i++) {
      const now = pad.buttons[i].pressed;
      this._padButtons[i] = now;
      if (now && !prev[i]) this._padPressed.add(i);
    }
    for (let i = 0; i < 4 && i < pad.axes.length; i++) this._padAxes[i] = pad.axes[i];
  }

  /** Continuous axis in [-1, 1]. Keyboard + gamepad, gamepad wins if non-zero. */
  axis(h) {
    let v = 0;
    if (h === 'x') {
      if (this.keys.has(AXIS_KEYS.right[0]) || this.keys.has(AXIS_KEYS.right[1])) v += 1;
      if (this.keys.has(AXIS_KEYS.left[0]) || this.keys.has(AXIS_KEYS.left[1])) v -= 1;
      v += deadzone(this._padAxes[0] || 0);
    } else if (h === 'y') {
      if (this.keys.has(AXIS_KEYS.up[0]) || this.keys.has(AXIS_KEYS.up[1])) v += 1;
      if (this.keys.has(AXIS_KEYS.down[0]) || this.keys.has(AXIS_KEYS.down[1])) v -= 1;
      v -= deadzone(this._padAxes[1] || 0); // screen-up is +y in our world
    }
    return Math.max(-1, Math.min(1, v));
  }

  /** Held state (keyboard key or gamepad button index). */
  down(action) {
    for (const code of ACTION_KEYS[action]) if (this.keys.has(code)) return true;
    const btn = PAD_BUTTONS[action];
    if (btn !== undefined && this._padButtons[btn]) return true;
    return false;
  }

  /** Edge-triggered press; drains the event so it fires exactly once. */
  pressedAction(action) {
    for (const code of ACTION_KEYS[action]) {
      if (this.pressed.has(code)) {
        this.pressed.delete(code);
        return true;
      }
    }
    for (const btn of PAD_BUTTONS[action]) {
      if (this._padPressed.has(btn)) {
        this._padPressed.delete(btn);
        return true;
      }
    }
    return false;
  }

  /** True if any input source is currently active (for "press any key" prompts). */
  anyPressed() {
    return this.pressed.size > 0 || this._padPressed.size > 0 || this._padButtons.some(Boolean);
  }

  /** Call at end of frame: clears edge-triggered state. */
  endFrame() {
    this.pressed.clear();
    this.released.clear();
    this._padPressed.clear();
  }

  dispose() {
    window.removeEventListener('keydown', this._boundKeyDown);
    window.removeEventListener('keyup', this._boundKeyUp);
    window.removeEventListener('blur', this._boundBlur);
    window.removeEventListener('gamepadconnected', this._boundPad);
    window.removeEventListener('gamepaddisconnected', this._boundPad);
  }
}

// Standard mapping: 0=A/Cross, 1=B/Circle, 2=X/Square, 3=Y/Triangle,
// 4=LB, 5=RB, 7=RT, 9=Start, 12=DpadUp.
const PAD_BUTTONS = {
  fire: [0, 2, 7],
  pause: [9],
  start: [9, 0],
};

/**
 * TimeScale — global time dilation (hit-stop / slow-mo).
 *
 * The Engine multiplies its delta by `TimeScale.value` every frame.
 * `freeze(value, durationMs)` pins the timescale for a short window, then
 * eases back to 1.0 exponentially. Multiple freezes stack by keeping the
 * strongest (lowest) value until its window expires.
 */
export default class TimeScale {
  constructor() {
    this.value = 1.0;
    this._frozen = 1.0;
    this._frozenUntil = 0; // performance.now() ms
  }

  /** Pin timescale to `value` for `durationMs` (e.g. freeze(0.05, 90)). */
  freeze(value, durationMs) {
    const now = performance.now();
    if (value < this._frozen || now >= this._frozenUntil) {
      this._frozen = value;
      this._frozenUntil = now + durationMs;
    }
    this.value = value;
  }

  /** Set a sustained timescale (slow-mo). Pass 1.0 to clear. */
  set(value) {
    this._frozen = value;
    this._frozenUntil = 0;
    this.value = value;
  }

  update(dt) {
    const now = performance.now();
    if (now < this._frozenUntil) {
      this.value = this._frozen;
    } else if (this.value < 1.0) {
      // Exponential ease back to 1.0 (frame-rate independent).
      this.value += (1.0 - this.value) * (1.0 - Math.exp(-dt * 14.0));
      if (1.0 - this.value < 0.001) this.value = 1.0;
    } else {
      this.value = 1.0;
    }
  }
}

import * as THREE from 'three';
import { randRange, clamp } from '../utils/Math.js';

/**
 * Centralized particle system.
 *
 * - ONE InstancedMesh for every particle in the scene (single draw call).
 * - HARD CAP of `maxParticles` (500 by default) live particles, enforced by a
 *   ring buffer: when the pool is saturated the oldest particle is recycled.
 * - Zero per-frame allocation: all state lives in pre-allocated Float32Arrays.
 * - Particles are billboarded planes with per-instance color and a soft
 *   radial-gradient alpha map (procedural), so they read as glowing embers
 *   under bloom without any custom shaders.
 */
export class ParticleManager {
  constructor(scene, { maxParticles = 500, alphaMap = null } = {}) {
    this.max = maxParticles;
    this.scene = scene;
    this.ring = 0;

    // State arrays (SoA layout, all pre-allocated).
    this.px = new Float32Array(maxParticles);
    this.py = new Float32Array(maxParticles);
    this.pz = new Float32Array(maxParticles);
    this.vx = new Float32Array(maxParticles);
    this.vy = new Float32Array(maxParticles);
    this.vz = new Float32Array(maxParticles);
    this.life = new Float32Array(maxParticles);
    this.maxLife = new Float32Array(maxParticles);
    this.size = new Float32Array(maxParticles);
    this.grav = new Float32Array(maxParticles);
    this.drag = new Float32Array(maxParticles);
    this.cr = new Float32Array(maxParticles);
    this.cg = new Float32Array(maxParticles);
    this.cb = new Float32Array(maxParticles);
    this.active = new Uint8Array(maxParticles);
    this.count = 0;

    const geo = new THREE.PlaneGeometry(1, 1);
    const mat = new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.95,
      alphaMap: alphaMap || null,
      alphaTest: 0.01,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
    });
    this.mesh = new THREE.InstancedMesh(geo, mat, maxParticles);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 20;

    // Allocate instanceColor and hide every instance at scale 0.
    const m = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const s = new THREE.Vector3(0, 0, 0);
    const p = new THREE.Vector3();
    for (let i = 0; i < maxParticles; i++) {
      m.compose(p, q, s);
      this.mesh.setMatrixAt(i, m);
      this.mesh.setColorAt(i, _WHITE);
    }
    this.mesh.instanceColor.needsUpdate = true;
    scene.add(this.mesh);

    // Scratch objects (reused every frame — no allocation in update()).
    this._m = m;
    this._q = q;
    this._s = s;
    this._p = p;
    this._c = new THREE.Color();
  }

  /**
   * Spawn a burst of particles.
   * @param {THREE.Vector3} origin
   * @param {object} o
   *   count, speed [min,max], size [min,max], life [min,max],
   *   color (hex or [hex,...] palette), dir (bias vector), spread (0..1 cone),
   *   gravity, drag
   */
  burst(origin, o = {}) {
    const count = Math.min(o.count ?? 24, this.max);
    const palette = Array.isArray(o.color) ? o.color : [o.color ?? 0x00ffff];
    const dir = o.dir || null;
    const spread = o.spread ?? 1;
    for (let n = 0; n < count; n++) {
      const i = this._alloc();
      this.px[i] = origin.x + (Math.random() - 0.5) * 0.15;
      this.py[i] = origin.y + (Math.random() - 0.5) * 0.15;
      this.pz[i] = origin.z + (Math.random() - 0.5) * 0.15;

      // Direction: random on sphere, biased toward `dir` by `spread`.
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      let dx = Math.sin(phi) * Math.cos(theta);
      let dy = Math.sin(phi) * Math.sin(theta);
      let dz = Math.cos(phi);
      if (dir) {
        dx = dx * (1 - spread) + dir.x * spread;
        dy = dy * (1 - spread) + dir.y * spread;
        dz = dz * (1 - spread) + dir.z * spread;
        const len = Math.hypot(dx, dy, dz) || 1;
        dx /= len; dy /= len; dz /= len;
      }
      const speed = randRange(o.speed?.[0] ?? 2, o.speed?.[1] ?? 6);
      this.vx[i] = dx * speed;
      this.vy[i] = dy * speed;
      this.vz[i] = dz * speed;

      this.life[i] = this.maxLife[i] = randRange(o.life?.[0] ?? 0.4, o.life?.[1] ?? 0.9);
      this.size[i] = randRange(o.size?.[0] ?? 0.08, o.size?.[1] ?? 0.22);
      this.grav[i] = o.gravity ?? 0;
      this.drag[i] = o.drag ?? 0;
      const col = palette[(Math.random() * palette.length) | 0];
      this._c.setHex(col);
      this.cr[i] = this._c.r;
      this.cg[i] = this._c.g;
      this.cb[i] = this._c.b;
      this.active[i] = 1;
    }
  }

  /** Continuous stream (e.g. thruster exhaust). */
  stream(origin, o = {}) {
    const n = Math.min(o.count ?? 1, this.max);
    for (let k = 0; k < n; k++) {
      const i = this._alloc();
      this.px[i] = origin.x + (Math.random() - 0.5) * (o.jitter ?? 0.1);
      this.py[i] = origin.y + (Math.random() - 0.5) * (o.jitter ?? 0.1);
      this.pz[i] = origin.z + (Math.random() - 0.5) * (o.jitter ?? 0.1);
      const dir = o.dir;
      const speed = randRange(o.speed?.[0] ?? 1, o.speed?.[1] ?? 3);
      this.vx[i] = dir.x * speed + (Math.random() - 0.5) * (o.spreadVel ?? 0.5);
      this.vy[i] = dir.y * speed + (Math.random() - 0.5) * (o.spreadVel ?? 0.5);
      this.vz[i] = dir.z * speed + (Math.random() - 0.5) * (o.spreadVel ?? 0.5);
      this.life[i] = this.maxLife[i] = randRange(o.life?.[0] ?? 0.2, o.life?.[1] ?? 0.5);
      this.size[i] = randRange(o.size?.[0] ?? 0.05, o.size?.[1] ?? 0.14);
      this.grav[i] = o.gravity ?? 0;
      this.drag[i] = o.drag ?? 0;
      const col = o.color ?? 0x00ffff;
      this._c.setHex(col);
      this.cr[i] = this._c.r;
      this.cg[i] = this._c.g;
      this.cb[i] = this._c.b;
      this.active[i] = 1;
    }
  }

  /** Ring-buffer allocation: recycles the oldest slot when saturated. */
  _alloc() {
    const i = this.ring;
    this.ring = (this.ring + 1) % this.max;
    if (!this.active[i]) this.count++;
    return i;
  }

  update(dt, camera) {
    if (dt <= 0) return;
    const m = this._m, q = this._q, s = this._s, p = this._p, c = this._c;
    let live = 0;
    for (let i = 0; i < this.max; i++) {
      if (!this.active[i]) continue;
      this.life[i] -= dt;
      if (this.life[i] <= 0) {
        this.active[i] = 0;
        m.compose(p.set(0, -9999, 0), q, s.set(0, 0, 0));
        this.mesh.setMatrixAt(i, m);
        continue;
      }
      live++;
      const dragK = this.drag[i] > 0 ? Math.max(0, 1 - this.drag[i] * dt) : 1;
      this.vx[i] *= dragK;
      this.vy[i] = this.vy[i] * dragK - this.grav[i] * dt;
      this.vz[i] *= dragK;
      this.px[i] += this.vx[i] * dt;
      this.py[i] += this.vy[i] * dt;
      this.pz[i] += this.vz[i] * dt;

      const t = this.life[i] / this.maxLife[i]; // 1 → 0
      const scale = this.size[i] * (0.35 + 0.65 * t);
      p.set(this.px[i], this.py[i], this.pz[i]);
      q.copy(camera.quaternion); // billboard
      s.set(scale, scale, scale);
      m.compose(p, q, s);
      this.mesh.setMatrixAt(i, m);
      // Fade toward black (additive blending → fades out visually).
      const fade = t < 0.4 ? t / 0.4 : 1;
      c.setRGB(this.cr[i] * fade, this.cg[i] * fade, this.cb[i] * fade);
      this.mesh.setColorAt(i, c);
    }
    this.count = live;
    this.mesh.instanceMatrix.needsUpdate = true;
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  clear() {
    this.active.fill(0);
    this.count = 0;
    const m = this._m, q = this._q, s = this._s, p = this._p;
    for (let i = 0; i < this.max; i++) {
      m.compose(p.set(0, -9999, 0), q, s.set(0, 0, 0));
      this.mesh.setMatrixAt(i, m);
    }
    this.mesh.instanceMatrix.needsUpdate = true;
  }

  dispose() {
    this.scene.remove(this.mesh);
    this.mesh.geometry.dispose();
    this.mesh.material.dispose();
  }
}

const _WHITE = new THREE.Color(0xffffff);

import * as THREE from 'three';
import ObjectPool from '../core/ObjectPool.js';

/**
 * Pooled expanding emissive rings for impacts and deaths (VFX #5).
 * Each ring is a flat torus (reads as a shockwave front) that scales up
 * and fades. Pooled — zero allocation per impact. Each ring owns its own
 * material so fades are independent.
 */
export class ShockwaveRings {
  /**
   * @param {import('../core/Engine.js').Engine} engine
   * @param {number} [maxRings=8]
   */
  constructor(engine, maxRings = 8) {
    this.engine = engine;
    this.maxRings = maxRings;

    this.geometry = new THREE.TorusGeometry(1, 0.05, 8, 48);

    this.pool = new ObjectPool(() => {
      const material = new THREE.MeshStandardMaterial({
        color: 0x000000,
        emissive: 0xffffff,
        emissiveIntensity: 3.0,
        roughness: 0.4,
        metalness: 0.0,
        transparent: true,
        opacity: 0.9,
      });
      const mesh = new THREE.Mesh(this.geometry, material);
      mesh.visible = false;
      mesh.renderOrder = 15;
      engine.scene.add(mesh);
      return {
        mesh,
        material,
        active: false,
        age: 0,
        duration: 0.5,
        maxScale: 2,
        startScale: 0.1,
        color: new THREE.Color(0xffffff),
      };
    }, maxRings);
  }

  /**
   * @param {THREE.Vector3} position
   * @param {number} [maxScale=2]
   * @param {number} [duration=0.5]
   * @param {number|THREE.Color} [color=0xffffff]
   * @param {number} [startScale=0.1]
   */
  spawn(position, maxScale = 2, duration = 0.5, color = 0xffffff, startScale = 0.1) {
    const ring = this.pool.acquire();
    if (!ring) return null;
    ring.active = true;
    ring.age = 0;
    ring.duration = duration;
    ring.maxScale = maxScale;
    ring.startScale = startScale;
    if (color instanceof THREE.Color) ring.color.copy(color);
    else ring.color.set(color);
    ring.mesh.position.copy(position);
    ring.mesh.scale.setScalar(Math.max(startScale, 0.001));
    ring.mesh.visible = true;
    ring.material.emissive.copy(ring.color);
    ring.material.opacity = 0.9;
    ring.material.emissiveIntensity = 3.0;
    return ring;
  }

  /** @param {number} dt real seconds */
  update(dt) {
    this.pool.forEachActive((ring) => {
      ring.age += dt;
      const t = Math.min(ring.age / ring.duration, 1);
      const s = ring.startScale + (ring.maxScale - ring.startScale) * (1 - Math.pow(1 - t, 3));
      ring.mesh.scale.setScalar(Math.max(s, 0.001));
      ring.material.opacity = 0.9 * (1 - t);
      ring.material.emissiveIntensity = 3.0 * (1 - t * 0.7);
      if (t >= 1) {
        ring.active = false;
        ring.mesh.visible = false;
        this.pool.release(ring);
      }
    });
  }

  clear() {
    this.pool.forEachActive((ring) => {
      ring.active = false;
      ring.mesh.visible = false;
    });
    this.pool.releaseAll();
  }

  dispose() {
    this.pool.forEachActive((ring) => this.engine.scene.remove(ring.mesh));
    this.pool.items.forEach((ring) => this.engine.scene.remove(ring.mesh));
    this.pool.items.forEach((ring) => ring.material.dispose());
    this.geometry.dispose();
  }
}

import * as THREE from 'three';
import ObjectPool from '../core/ObjectPool.js';

/**
 * MotionTrails — pooled fading ribbons for fast-moving objects (VFX #4).
 *
 * Each trail owns its own BufferGeometry (so per-trail fade is exact) and a
 * shared LineBasicMaterial. The owner calls track(id, x, y, z) every frame
 * while the object moves; the trail keeps the last `segments` positions with
 * a head-bright → tail-dark vertex gradient. When an id stops being tracked
 * (or release() is called) the trail fades out over `fadeMs` and retires to
 * the pool.
 */
export class MotionTrails {
  constructor(scene, { maxTrails = 10, segments = 14, color = 0x66ffff } = {}) {
    this.scene = scene;
    this.maxTrails = maxTrails;
    this.segments = segments;
    this.baseColor = new THREE.Color(color);

    this.material = new THREE.LineBasicMaterial({
      vertexColors: true,
      transparent: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });

    this.pool = new ObjectPool(() => {
      const geometry = new THREE.BufferGeometry();
      const positions = new Float32Array(segments * 3);
      const colors = new Float32Array(segments * 3);
      geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3).setUsage(THREE.DynamicDrawUsage));
      geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3).setUsage(THREE.DynamicDrawUsage));
      geometry.setDrawRange(0, 0);
      const line = new THREE.Line(geometry, this.material);
      line.frustumCulled = false;
      line.visible = false;
      scene.add(line);
      return {
        line,
        geometry,
        positions,
        colors,
        count: 0,
        lastTime: 0,
        fading: 0, // 0 = not fading; otherwise performance.now() deadline
        fadeRate: 0, // opacity units per ms while fading
      };
    }, maxTrails);

    this.active = new Map(); // id -> trail record
  }

  /** Record a position for trail `id`. Creates the trail on first use. */
  track(id, x, y, z) {
    let rec = this.active.get(id);
    if (!rec) {
      rec = this.pool.acquire();
      if (!rec) {
        // Budget exhausted: steal the oldest tracked trail.
        const oldestId = this.active.keys().next().value;
        rec = this.active.get(oldestId);
        this.active.delete(oldestId);
      }
      this.active.set(id, rec);
      rec.count = 0;
      rec.fading = 0;
      rec.lastTime = performance.now();
    }
    rec.lastTime = performance.now();
    rec.fading = 0;

    const pos = rec.positions;
    for (let i = (this.segments - 1) * 3; i >= 3; i--) {
      pos[i] = pos[i - 3];
      pos[i + 1] = pos[i - 2];
      pos[i + 2] = pos[i - 1];
    }
    pos[0] = x; pos[1] = y; pos[2] = z;
    rec.count = Math.min(rec.count + 1, this.segments);

    const col = rec.colors;
    const c = this.baseColor;
    for (let i = 0; i < this.segments; i++) {
      const t = i / (this.segments - 1); // 0 head, 1 tail
      const a = (1 - t) * (1 - t);
      col[i * 3] = c.r * a;
      col[i * 3 + 1] = c.g * a;
      col[i * 3 + 2] = c.b * a;
    }
    rec.geometry.attributes.position.needsUpdate = true;
    rec.geometry.attributes.color.needsUpdate = true;
    rec.geometry.setDrawRange(0, rec.count);
    rec.line.visible = true;
  }

  /** Stop a trail: it fades out over `fadeMs` then retires to the pool. */
  release(id, fadeMs = 260) {
    const rec = this.active.get(id);
    if (!rec) return;
    this.active.delete(id);
    rec.fading = performance.now() + fadeMs;
    rec.fadeRate = 1 / Math.max(fadeMs, 1);
  }

  /** @param {number} dt real seconds (unused for timing; we use wall clock) */
  update(dt) {
    const now = performance.now();
    for (const [id, rec] of this.active) {
      // Object stopped moving: begin fade-out.
      if (!rec.fading && rec.lastTime < now - 90) {
        rec.fading = now + 260;
        rec.fadeRate = 1 / 260;
      }
    }
    for (let i = 0; i < this.pool.active.length; i++) {
      const rec = this.pool.active[i];
      if (!rec.fading) continue;
      if (now >= rec.fading) {
        rec.line.visible = false;
        rec.fading = 0;
        this.pool.release(rec);
      } else {
        // Fade the whole ribbon toward black (additive → fades out).
        const k = Math.max(0, 1 - (now - (rec.fading - 260)) * rec.fadeRate);
        const col = rec.colors;
        for (let j = 0; j < col.length; j++) col[j] *= k;
        rec.geometry.attributes.color.needsUpdate = true;
      }
    }
  }

  clear() {
    for (const id of [...this.active.keys()]) this.release(id, 0);
    for (const rec of this.pool.active) {
      rec.line.visible = false;
      rec.fading = 0;
    }
    this.pool.releaseAll();
    this.active.clear();
  }

  dispose() {
    for (const rec of this.pool.items) rec.geometry.dispose();
    this.material.dispose();
  }
}

import * as THREE from 'three';

/**
 * FloatingText — pooled DOM score popups projected from world space.
 *
 * Six required VFX, #6. Each popup is a div in a fixed overlay layer;
 * its screen position is computed per frame with Vector3.project(camera)
 * while it is alive, then a CSS animation carries the rise + fade.
 * Pool of 12 — no DOM churn in the hot path.
 */
export default class FloatingText {
  constructor({ layer, max = 12 } = {}) {
    if (!layer) throw new Error('FloatingText: `layer` element required');
    this.layer = layer;
    this.max = max;
    this.items = [];
    this._v = new THREE.Vector3();

    for (let i = 0; i < max; i++) {
      const el = document.createElement('div');
      el.className = 'float-text';
      el.style.display = 'none';
      layer.appendChild(el);
      this.items.push({ el, active: false, pos: { x: 0, y: 0, z: 0 }, life: 0, maxLife: 0 });
    }
    this._cursor = 0;
  }

  /**
   * Spawn a popup at a world position.
   * @param {number} wx @param {number} wy @param {number} wz
   * @param {string} text
   * @param {object} [opts] { color, size, life }
   */
  spawn(wx, wy, wz, text, opts = {}) {
    const it = this.items[this._cursor];
    this._cursor = (this._cursor + 1) % this.max;
    it.active = true;
    it.pos.x = wx; it.pos.y = wy; it.pos.z = wz;
    it.life = 0;
    it.maxLife = opts.life ?? 0.9;
    it.el.textContent = text;
    it.el.style.color = opts.color || '#7df9ff';
    it.el.style.fontSize = `${opts.size ?? 15}px`;
    it.el.style.display = 'block';
    it.el.style.opacity = '1';
    it.el.style.transform = 'translate(-50%, -50%) scale(0.6)';
    // force reflow so the transition restarts on reused elements
    void it.el.offsetWidth;
    it.el.style.transition = `transform ${it.maxLife}s cubic-bezier(.2,.7,.3,1), opacity ${it.maxLife}s ease-out`;
    it.el.style.transform = 'translate(-50%, -160%) scale(1.15)';
    it.el.style.opacity = '0';
    return it;
  }

  /** Per-frame: project live popups to screen space. */
  update(dt, camera, width, height) {
    const v = this._v;
    for (const it of this.items) {
      if (!it.active) continue;
      it.life += dt;
      if (it.life >= it.maxLife) {
        it.active = false;
        it.el.style.display = 'none';
        continue;
      }
      v.x = it.pos.x; v.y = it.pos.y; v.z = it.pos.z;
      v.project(camera);
      const x = (v.x * 0.5 + 0.5) * width;
      const y = (-v.y * 0.5 + 0.5) * height;
      it.el.style.left = `${x}px`;
      it.el.style.top = `${y}px`;
    }
  }

  clear() {
    for (const it of this.items) {
      it.active = false;
      it.el.style.display = 'none';
    }
  }

  dispose() {
    for (const it of this.items) it.el.remove();
  }
}

// shared/audio/AudioEngine.js
// 100% procedural sound effects via the Web Audio API. No audio files.
//
// Architecture:
//   source(s) -> [filter] -> gain envelope -> bus (lowpass) -> master -> destination
//
// Every voice is a small graph built and torn down per call; the only
// persistent nodes are master, bus, and the compressor. All parameters are
// scheduled with the audio clock (ctx.currentTime) so timing is sample-accurate
// and independent of JS frame jitter.

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.bus = null;
    this.muted = false;
    this.volume = 0.8;
  }

  // Must be called from a user gesture (browser autoplay policy).
  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return; // no audio support: everything below is a no-op
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : this.volume;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 24;
    comp.ratio.value = 6;
    this.bus = this.ctx.createGain();
    this.bus.gain.value = 0.9;
    this.bus.connect(comp);
    comp.connect(this.master);
    this.master.connect(this.ctx.destination);
  }

  get ready() { return !!this.ctx; }

  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.value = m ? 0 : this.volume;
  }

  // ---------------------------------------------------------------- voices

  // Generic enveloped oscillator.
  _tone({ type = 'square', freq = 440, freqEnd = null, dur = 0.2, vol = 0.3,
          attack = 0.005, decay = null, filterFreq = null, filterQ = 1,
          when = 0, detune = 0 }) {
    if (!this.ctx) return;
    const t0 = this.ctx.currentTime + when;
    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    osc.detune.value = detune;
    if (freqEnd !== null) {
      osc.frequency.exponentialRampToValueAtTime(Math.max(1, freqEnd), t0 + dur);
    }
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(vol, t0 + attack);
    const releaseAt = t0 + (decay !== null ? decay : dur);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur + 0.05);
    void releaseAt;
    let head = osc;
    if (filterFreq) {
      const f = this.ctx.createBiquadFilter();
      f.type = 'lowpass';
      f.frequency.value = filterFreq;
      f.Q.value = filterQ;
      head.connect(f);
      head = f;
    }
    head.connect(g);
    g.connect(this.bus);
    osc.start(t0);
    osc.stop(t0 + dur + 0.1);
    osc.onended = () => { osc.disconnect(); g.disconnect(); };
  }

  // Filtered white-noise burst (explosions, impacts).
  _noise({ dur = 0.3, vol = 0.4, filterFreq = 1200, filterEnd = null,
           type = 'lowpass', when = 0, q = 0.8 }) {
    if (!this.ctx) return;
    const t0 = this.ctx.currentTime + when;
    const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.Q.value = q;
    f.frequency.setValueAtTime(filterFreq, t0);
    if (filterEnd !== null) {
      f.frequency.exponentialRampToValueAtTime(Math.max(20, filterEnd), t0 + dur);
    }
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(f); f.connect(g); g.connect(this.bus);
    src.start(t0);
    src.onended = () => { src.disconnect(); f.disconnect(); g.disconnect(); };
  }

  // ------------------------------------------------------------- game SFX

  laser() {
    this._tone({ type: 'sawtooth', freq: 1400, freqEnd: 220, dur: 0.14,
                 vol: 0.16, filterFreq: 3200 });
  }

  invaderKill() {
    this._noise({ dur: 0.22, vol: 0.3, filterFreq: 2400, filterEnd: 180 });
    this._tone({ type: 'square', freq: 220, freqEnd: 55, dur: 0.18, vol: 0.2 });
  }

  playerHit() {
    this._noise({ dur: 0.6, vol: 0.5, filterFreq: 3000, filterEnd: 90 });
    this._tone({ type: 'sawtooth', freq: 300, freqEnd: 40, dur: 0.55, vol: 0.3 });
    this._tone({ type: 'square', freq: 150, freqEnd: 30, dur: 0.5, vol: 0.2, when: 0.05 });
  }

  shieldHit() {
    this._noise({ dur: 0.08, vol: 0.14, filterFreq: 1800, filterEnd: 400 });
  }

  bonusSpawn() {
    this._tone({ type: 'square', freq: 660, dur: 0.07, vol: 0.12 });
    this._tone({ type: 'square', freq: 880, dur: 0.07, vol: 0.12, when: 0.08 });
    this._tone({ type: 'square', freq: 1320, dur: 0.1, vol: 0.12, when: 0.16 });
  }

  bonusKill() {
    this._noise({ dur: 0.3, vol: 0.35, filterFreq: 3200, filterEnd: 200 });
    this._tone({ type: 'square', freq: 880, freqEnd: 1760, dur: 0.25, vol: 0.15 });
  }

  oneUp() {
    const notes = [523.25, 659.25, 783.99, 1046.5];
    notes.forEach((f, i) =>
      this._tone({ type: 'square', freq: f, dur: 0.12, vol: 0.16, when: i * 0.09 }));
  }

  waveClear() {
    const notes = [392, 523.25, 659.25, 783.99, 1046.5];
    notes.forEach((f, i) =>
      this._tone({ type: 'triangle', freq: f, dur: 0.16, vol: 0.2, when: i * 0.1 }));
  }

  gameOver() {
    const notes = [440, 349.23, 293.66, 220];
    notes.forEach((f, i) =>
      this._tone({ type: 'sawtooth', freq: f, dur: 0.3, vol: 0.18, when: i * 0.22,
                   filterFreq: 2000 }));
  }

  uiSelect() {
    this._tone({ type: 'square', freq: 880, dur: 0.06, vol: 0.1 });
  }

  // Classic 4-note invader march. `step` is 0..3, `tempo` scales note length.
  march(step) {
    const base = [110, 98, 87.31, 77.78];
    this._tone({ type: 'square', freq: base[step & 3], dur: 0.11, vol: 0.14,
                 filterFreq: 900 });
  }

  dispose() {
    if (this.ctx) {
      this.ctx.close();
      this.ctx = null;
      this.master = null;
      this.bus = null;
    }
  }
}

/**
 * MusicSequencer — lookahead-scheduled step sequencer. 100% procedural:
 * every voice is an oscillator or a noise buffer, scheduled sample-accurate
 * against AudioContext time. No audio files.
 *
 * The AudioContext is resolved lazily (AudioEngine.init() runs on the first
 * user gesture, which is always after construction), so `ctx`/`master` are
 * read through the audio engine on every schedule tick.
 *
 * Track format:
 *   {
 *     bpm: number,
 *     bass: [midi|0 ×8],        // 0 = rest
 *     arp:  [midi|0 ×8],
 *     hat:  [0|1 ×8],
 *     bassWave: 'sawtooth'|'square'|'triangle',
 *     bassCutoff: number (Hz),
 *   }
 */

const midiToFreq = (m) => 440 * Math.pow(2, (m - 69) / 12);

export default class MusicSequencer {
  constructor(audio) {
    this.audio = audio;
    this.timer = null;
    this.step = 0;
    this.nextNoteTime = 0;
    this.track = null;
    this.intensity = 0.5;
    this.playing = false;
    this._noise = null; // built lazily once the context exists
  }

  _ctx() { return this.audio.ctx; }
  _master() { return this.audio.master; }

  _ensureNoise() {
    const ctx = this._ctx();
    if (!this._noise && ctx) {
      const len = ctx.sampleRate; // 1 second
      const buf = ctx.createBuffer(1, len, ctx.sampleRate);
      const d = buf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      this._noise = buf;
    }
  }

  setTrack(track) { this.track = track; }

  setIntensity(v) { this.intensity = Math.max(0, Math.min(1, v)); }

  start() {
    if (this.playing || !this.track || !this._ctx()) return;
    this.playing = true;
    this.step = 0;
    this.nextNoteTime = this._ctx().currentTime + 0.08;
    this.timer = setInterval(() => this._schedule(), 25);
  }

  stop() {
    this.playing = false;
    if (this.timer !== null) { clearInterval(this.timer); this.timer = null; }
  }

  _schedule() {
    const ctx = this._ctx();
    if (!ctx || !this.track) return;
    const t = this.track;
    const secondsPerStep = 60 / t.bpm / 2; // 8th notes
    // If the tab was backgrounded, resync instead of dumping a burst.
    if (this.nextNoteTime < ctx.currentTime - 0.5) {
      this.nextNoteTime = ctx.currentTime + 0.05;
    }
    while (this.nextNoteTime < ctx.currentTime + 0.12) {
      this._scheduleStep(this.step, this.nextNoteTime, t, secondsPerStep);
      this.step = (this.step + 1) % 8;
      this.nextNoteTime += secondsPerStep;
    }
  }

  _scheduleStep(i, time, t, sps) {
    const ctx = this._ctx();
    const master = this._master();
    if (!ctx || !master) return;

    // --- bass ---
    const bm = t.bass[i];
    if (bm) {
      const osc = ctx.createOscillator();
      osc.type = t.bassWave || 'sawtooth';
      osc.frequency.value = midiToFreq(bm);
      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = (t.bassCutoff || 320) * (0.6 + this.intensity);
      filter.Q.value = 6;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, time);
      g.gain.exponentialRampToValueAtTime(0.16 + 0.1 * this.intensity, time + 0.01);
      g.gain.exponentialRampToValueAtTime(0.0001, time + sps * 0.9);
      osc.connect(filter); filter.connect(g); g.connect(master);
      osc.start(time); osc.stop(time + sps);
    }

    // --- arp (only when intensity is up, so menus stay sparse) ---
    const am = t.arp[i];
    if (am && this.intensity > 0.15) {
      const osc = ctx.createOscillator();
      osc.type = 'square';
      osc.frequency.value = midiToFreq(am + (this.intensity > 0.7 ? 12 : 0));
      const g = ctx.createGain();
      const vol = 0.028 * this.intensity;
      g.gain.setValueAtTime(0.0001, time);
      g.gain.exponentialRampToValueAtTime(vol, time + 0.005);
      g.gain.exponentialRampToValueAtTime(0.0001, time + sps * 0.55);
      osc.connect(g); g.connect(master);
      osc.start(time); osc.stop(time + sps * 0.6);
    }

    // --- hat ---
    if (t.hat && t.hat[i]) {
      this._ensureNoise();
      const src = ctx.createBufferSource();
      src.buffer = this._noise;
      const hp = ctx.createBiquadFilter();
      hp.type = 'highpass';
      hp.frequency.value = 6500;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.05 + 0.04 * this.intensity, time);
      g.gain.exponentialRampToValueAtTime(0.0001, time + 0.045);
      src.connect(hp); hp.connect(g); g.connect(master);
      src.start(time); src.stop(time + 0.06);
    }
  }

  dispose() {
    this.stop();
  }
}

/**
 * GlassUI — glassmorphism HUD + full-screen states (menu / pause / game over).
 *
 * Slot-based API so any game in the collection can drive it without touching
 * DOM structure:
 *
 *   ui.setHudSlot('score', '12 400');
 *   ui.showScreen('menu', { title: 'NEON INVADERS', lines: [...], primary: 'START' });
 *   ui.onPrimary = () => game.start();
 *
 * All DOM is created here and disposed on destroy() — no external markup.
 */

export class GlassUI {
  constructor(root) {
    this.root = root;
    this.onPrimary = null;
    this.onSecondary = null;

    this.hud = document.createElement('div');
    this.hud.className = 'glass-hud';
    this.slots = new Map();

    this.screen = document.createElement('div');
    this.screen.className = 'glass-screen';
    this.screen.hidden = true;

    this._buildHud();
    this._buildScreen();
    root.appendChild(this.hud);
    root.appendChild(this.screen);
  }

  _buildHud() {
    const left = document.createElement('div');
    left.className = 'hud-cluster hud-left';
    const right = document.createElement('div');
    right.className = 'hud-cluster hud-right';

    const mk = (label, cls) => {
      const el = document.createElement('div');
      el.className = `hud-slot ${cls}`;
      const lab = document.createElement('span');
      lab.className = 'hud-label';
      lab.textContent = label;
      const val = document.createElement('span');
      val.className = 'hud-value';
      el.append(lab, val);
      return { el, val };
    };

    const score = mk('SCORE', 'score');
    const wave = mk('WAVE', 'wave');
    const lives = mk('LIVES', 'lives');
    const combo = mk('COMBO', 'combo');
    combo.el.classList.add('combo-slot');
    combo.el.style.display = 'none';

    left.append(score.el, wave.el);
    right.append(lives.el, combo.el);
    this.hud.append(left, right);

    this.slots.set('score', score.val);
    this.slots.set('wave', wave.val);
    this.slots.set('lives', lives.val);
    this.slots.set('combo', combo.el);
  }

  _buildScreen() {
    this.screenTitle = document.createElement('h1');
    this.screenTitle.className = 'screen-title';

    this.screenSub = document.createElement('p');
    this.screenSub.className = 'screen-sub';

    this.screenLines = document.createElement('div');
    this.screenLines.className = 'screen-lines';

    this.btnPrimary = document.createElement('button');
    this.btnPrimary.className = 'glass-btn primary';
    this.btnPrimary.addEventListener('click', () => this.onPrimary && this.onPrimary());

    this.btnSecondary = document.createElement('button');
    this.btnSecondary.className = 'glass-btn';
    this.btnSecondary.addEventListener('click', () => this.onSecondary && this.onSecondary());

    this.screen.append(
      this.screenTitle,
      this.screenSub,
      this.screenLines,
      this.btnPrimary,
      this.btnSecondary
    );
  }

  setHudSlot(name, text) {
    const slot = this.slots.get(name);
    if (slot) slot.textContent = text;
  }

  setCombo(multiplier) {
    const el = this.slots.get('combo');
    if (!el) return;
    if (multiplier > 1) {
      el.style.display = '';
      el.querySelector('.hud-value').textContent = `×${multiplier}`;
    } else {
      el.style.display = 'none';
    }
  }

  showScreen(kind, opts = {}) {
    this.screen.hidden = false;
    this.screenTitle.textContent = opts.title || '';
    this.screenSub.textContent = opts.sub || '';

    this.screenLines.textContent = '';
    for (const line of opts.lines || []) {
      const p = document.createElement('p');
      p.textContent = line;
      this.screenLines.appendChild(p);
    }

    this.btnPrimary.textContent = opts.primary || 'START';
    this.btnPrimary.hidden = !opts.primary;
    this.btnSecondary.textContent = opts.secondary || '';
    this.btnSecondary.hidden = !opts.secondary;
    this.screen.dataset.kind = kind;
  }

  hideScreen() {
    this.screen.hidden = true;
  }

  hideHud() {
    this.hud.style.display = 'none';
  }

  showHud() {
    this.hud.style.display = '';
  }

  destroy() {
    this.hud.remove();
    this.screen.remove();
    this.slots.clear();
  }
}

// Space_Invaders/main.js — bootstrap.
// Builds the shared service layer (input, time, VFX, audio, UI), injects it
// into the game, owns the window lifecycle, and disposes everything on
// teardown. This is the single file that changes when switching games.

import { Engine } from '../shared/core/Engine.js';
import Input from '../shared/core/Input.js';
import TimeScale from '../shared/core/TimeScale.js';
import { Composer } from '../shared/postfx/Composer.js';
import { ParticleManager } from '../shared/vfx/ParticleManager.js';
import { ShockwaveRings } from '../shared/vfx/ShockwaveRings.js';
import { MotionTrails } from '../shared/vfx/MotionTrails.js';
import FloatingText from '../shared/vfx/FloatingText.js';
import CameraShake from '../shared/vfx/CameraShake.js';
import { AudioEngine } from '../shared/audio/AudioEngine.js';
import MusicSequencer from '../shared/audio/MusicSequencer.js';
import { GlassUI } from '../shared/ui/GlassUI.js';
import { makeGlowTexture } from '../shared/utils/Procedural.js';
import { CONFIG } from './config.js';
import SpaceInvadersGame from './SpaceInvadersGame.js';

import '../shared/ui/glass.css';

const app = document.getElementById('app');
const uiRoot = document.getElementById('ui-root');

// ---------------------------------------------------------------- engine
const engine = new Engine({
  canvas: document.createElement('canvas'),
  width: window.innerWidth,
  height: window.innerHeight,
  background: 0x050510,
  exposure: 1.1,
});
app.appendChild(engine.renderer.domElement);

const composer = new Composer(engine, CONFIG.vfx.bloom);
engine.addDisposable(composer);

// ---------------------------------------------------------------- services
const input = new Input();
const timescale = new TimeScale();
engine.timescale = timescale;

const audio = new AudioEngine();
audio.volume = CONFIG.audio.volume;
const music = new MusicSequencer(audio);

const ui = new GlassUI(uiRoot);

// VFX (all pooled, all disposed via engine.disposables or game.dispose).
const glow = makeGlowTexture(128);
const particles = new ParticleManager(engine.scene, {
  maxParticles: CONFIG.vfx.particleCap,
  alphaMap: glow,
});
const rings = new ShockwaveRings(engine, CONFIG.vfx.ringCap);
const trails = new MotionTrails(engine.scene, {
  maxTrails: CONFIG.vfx.trailCap,
  segments: CONFIG.vfx.trailSegments,
});
const text = new FloatingText({ layer: uiRoot, max: CONFIG.vfx.textCap });
const shake = new CameraShake(engine.camera, CONFIG.vfx.shake);

engine.addDisposable(particles);
engine.addDisposable(rings);
engine.addDisposable(trails);
engine.addDisposable(text);
engine.addDisposable(input);
engine.addDisposable(audio);
engine.addDisposable(music);
engine.addDisposable(ui);
engine.addDisposable(glow);

// ---------------------------------------------------------------- game
const game = new SpaceInvadersGame({
  engine,
  input,
  timescale,
  audio,
  music,
  ui,
  particles,
  rings,
  trails,
  text,
  shake,
});
engine.addDisposable(game);

// ---------------------------------------------------------------- lifecycle
function onResize() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  engine.resize(w, h);
  composer.resize(w, h);
  game.onResize(w, h);
}
window.addEventListener('resize', onResize);

engine.onUpdate((dt, raw) => game.update(dt, raw));
engine.start();

// Teardown (HMR / navigation): release GPU resources and listeners.
if (import.meta.hot) {
  import.meta.hot.dispose(() => {
    window.removeEventListener('resize', onResize);
    engine.dispose(); // disposes game + all services + renderer
  });
}

// Space_Invaders/entities/InvaderFormation.js
// The 10×5 grid of invaders, rendered as three InstancedMeshes (one per
// species) — one draw call per species for the whole field.
//
// Classic step motion: the whole formation jumps `stepDX` units every
// `interval` seconds; `interval` is a pure function of survivors (frantic
// at 50, slow at 1). On a wall bounce the formation descends `stepDY`.
// Two-frame animation swaps each species' geometry (frame 0/1) per step.
//
// Collision data (world positions, radii) is exposed for the game layer.

import * as THREE from 'three';
import { makeInvaderGeometry } from '../../shared/utils/Procedural.js';
import { clamp } from '../../shared/utils/Math.js';

export class InvaderFormation {
  /**
   * @param {import('../../shared/core/Engine.js').Engine} engine
   * @param {object} cfg the CONFIG object from config.js
   */
  constructor(engine, cfg) {
    this.engine = engine;
    this.cfg = cfg;
    const F = cfg.invader;

    this.cols = F.cols;
    this.rows = F.rows;
    this.total = this.cols * this.rows;
    this.radius = F.radius;

    // Per-cell layout (world units, relative to the formation offset).
    this.cellW = F.spacingX;
    this.cellH = F.spacingY;
    this.originX = F.startX;
    this.originY = F.startY;

    // Invader records.
    this.invaders = [];
    for (let r = 0; r < this.rows; r++) {
      for (let c = 0; c < this.cols; c++) {
        this.invaders.push({
          col: c,
          row: r,
          species: F.speciesByRow[r],
          baseX: this.originX + c * this.cellW,
          baseY: this.originY - r * this.cellH,
          alive: true,
        });
      }
    }

    // Geometries: 3 species × 2 frames (pixel-art sheet cells).
    const w = 0.85;
    const h = 0.7;
    this.geos = [];
    for (let s = 0; s < 3; s++) {
      this.geos.push([
        makeInvaderGeometry(w, h, s, 0),
        makeInvaderGeometry(w, h, s, 1),
      ]);
    }

    // One InstancedMesh + material per species.
    this.meshes = [];
    this.materials = [];
    for (let s = 0; s < 3; s++) {
      const count = this.invaders.filter((v) => v.species === s).length;
      const mat = new THREE.MeshStandardMaterial({
        color: 0x0a0a14,
        emissive: new THREE.Color(F.colorBySpecies[s]),
        emissiveIntensity: 1.7,
        roughness: 0.5,
        metalness: 0.1,
        side: THREE.DoubleSide,
      });
      const mesh = new THREE.InstancedMesh(this.geos[s][0], mat, count);
      mesh.frustumCulled = false;
      mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      engine.scene.add(mesh);
      this.meshes.push(mesh);
      this.materials.push(mat);
    }

    // Formation state.
    this.fx = 0;
    this.fy = 0;
    this.dir = 1;
    this.frame = 0;
    this.stepTimer = 0;
    this.aliveCount = this.total;
    this.pulse = 0; // emissive pulse, decays each frame
    this._time = 0; // accumulated, drives the row-phase bob

    // Wave-scaled motion params (set by reset()).
    this.baseInterval = F.maxInterval;
    this.baseIntervalMin = F.minInterval;
    this.step = F.stepDX;
    this.descent = F.stepDY;

    // Scratch (no per-frame allocation).
    this._m = new THREE.Matrix4();
    this._q = new THREE.Quaternion();
    this._s = new THREE.Vector3();
    this._p = new THREE.Vector3();

    this.reset(1);
  }

  /** (Re)initialize for a wave. */
  reset(wave) {
    const F = this.cfg.invader;
    this.fx = 0;
    this.fy = 0;
    this.dir = 1;
    this.frame = 0;
    this.stepTimer = 0;
    this.aliveCount = this.total;
    for (const v of this.invaders) v.alive = true;
    // Each wave is faster and descends a touch more.
    const k = Math.max(0.45, 1 - 0.08 * (wave - 1));
    this.baseInterval = F.maxInterval * k;
    this.baseIntervalMin = F.minInterval * k;
    this.descent = F.stepDY * (1 + 0.06 * (wave - 1));
    this.step = F.stepDX;
    this._applyFrameGeometry();
    this._writeMatrices(0);
  }

  /** interval(n) — pure function of survivors (classic acceleration). */
  intervalFor(n) {
    const t = (n - 1) / (this.total - 1); // 1 = full, 0 = one left
    return this.baseIntervalMin + (this.baseInterval - this.baseIntervalMin) * t;
  }

  /** Advance formation. Returns number of steps taken this frame. */
  update(dt) {
    if (this.aliveCount === 0) return 0;
    this._time += dt;
    this.stepTimer += dt;
    let steps = 0;
    let guard = 0;
    while (this.stepTimer >= this.intervalFor(this.aliveCount) && guard++ < 8) {
      this.stepTimer -= this.intervalFor(this.aliveCount);
      this._step();
      steps++;
    }
    // Emissive pulse decay.
    this.pulse = Math.max(0, this.pulse - dt * 6);
    this._writeMatrices(this._time);
    for (const mat of this.materials) {
      mat.emissiveIntensity = 1.7 + this.pulse;
    }
    return steps;
  }

  _step() {
    const minX = this._liveMinX();
    const maxX = this._liveMaxX();
    const bound = this.cfg.invader.wallLimit;
    let bounced = false;
    if (this.dir > 0 && maxX + this.step > bound) {
      this.dir = -1;
      bounced = true;
    } else if (this.dir < 0 && minX - this.step < -bound) {
      this.dir = 1;
      bounced = true;
    }
    if (bounced) {
      this.fy -= this.descent;
    } else {
      this.fx += this.dir * this.step;
    }
    this.frame ^= 1;
    this.pulse = 1.0;
    this._applyFrameGeometry();
  }

  _applyFrameGeometry() {
    for (let s = 0; s < 3; s++) {
      this.meshes[s].geometry = this.geos[s][this.frame];
    }
  }

  _liveMinX() {
    let m = Infinity;
    for (const v of this.invaders) {
      if (v.alive) m = Math.min(m, v.baseX + this.fx);
    }
    return m;
  }

  _liveMaxX() {
    let m = -Infinity;
    for (const v of this.invaders) {
      if (v.alive) m = Math.max(m, v.baseX + this.fx);
    }
    return m;
  }

  _writeMatrices(time) {
    // Per-species instance index counter (order must match killAt()).
    const idx = [0, 0, 0];
    const m = this._m, q = this._q, s = this._s, p = this._p;
    for (const v of this.invaders) {
      if (!v.alive) continue;
      const i = idx[v.species]++;
      // Row-phase bob: subtle vertical shimmer, phase-offset by row/col.
      const bob = Math.sin(time * 2.2 + v.row * 0.9 + v.col * 0.35) * 0.045;
      p.set(v.baseX + this.fx, v.baseY + this.fy + bob, 0);
      const sc = 1 + this.pulse * 0.06;
      s.set(sc, sc, 1);
      m.compose(p, q, s);
      this.meshes[v.species].setMatrixAt(i, m);
    }
    for (let sp = 0; sp < 3; sp++) {
      this.meshes[sp].instanceMatrix.needsUpdate = true;
    }
  }

  /**
   * Kill the invader at (col, row). Returns a world-space record
   * { species, x, y, z } or null if that cell is already dead.
   */
  killAt(col, row) {
    const v = this.invaders.find((x) => x.alive && x.col === col && x.row === row);
    if (!v) return null;
    v.alive = false;
    this.aliveCount--;
    // Hide the instance: scale 0 at its slot.
    const i = this._instanceIndex(v);
    const m = this._m;
    m.makeScale(0, 0, 0);
    m.setPosition(v.baseX + this.fx, v.baseY + this.fy, 0);
    this.meshes[v.species].setMatrixAt(i, m);
    this.meshes[v.species].instanceMatrix.needsUpdate = true;
    return {
      species: v.species,
      x: v.baseX + this.fx,
      y: v.baseY + this.fy,
      z: 0,
    };
  }

  /** Instance slot of a live invader (same order as _writeMatrices). */
  _instanceIndex(v) {
    let i = 0;
    for (const u of this.invaders) {
      if (!u.alive) continue;
      if (u === v) return i;
      if (u.species === v.species) i++;
    }
    return i;
  }

  /** Lowest live invader in a column (classic shooter rule). */
  bottomShooter(col) {
    let best = null;
    for (const v of this.invaders) {
      if (!v.alive || v.col !== col) continue;
      if (!best || v.row > best.row) best = v;
    }
    return best;
  }

  /** World position of an invader record. */
  worldPos(v) {
    return { x: v.baseX + this.fx, y: v.baseY + this.fy, z: 0 };
  }

  /** Call fn(inv) for every live invader (inv has world x/y + species). */
  forEachAlive(fn) {
    for (const v of this.invaders) {
      if (!v.alive) continue;
      fn({
        col: v.col,
        row: v.row,
        species: v.species,
        x: v.baseX + this.fx,
        y: v.baseY + this.fy,
        z: 0,
      });
    }
  }

  /**
   * First live invader whose circle touches the player circle.
   * Returns { x, y, z, species } or null.
   */
  firstContact(px, py, sumRadius) {
    const r2 = sumRadius * sumRadius;
    for (const v of this.invaders) {
      if (!v.alive) continue;
      const dx = v.baseX + this.fx - px;
      const dy = v.baseY + this.fy - py;
      if (dx * dx + dy * dy < r2) {
        return { x: v.baseX + this.fx, y: v.baseY + this.fy, z: 0, species: v.species };
      }
    }
    return null;
  }

  /** True if any live invader has reached the invasion line. */
  hasInvaded(playerY) {
    const margin = 1.2;
    for (const v of this.invaders) {
      if (v.alive && v.baseY + this.fy <= playerY + margin) return true;
    }
    return false;
  }

  dispose() {
    for (const mesh of this.meshes) this.engine.scene.remove(mesh);
    for (const pair of this.geos) for (const g of pair) g.dispose();
    for (const mat of this.materials) mat.dispose();
  }
}

// Space_Invaders/entities/Player.js
// Player cannon — a small PBR ship built from primitives (hull, cockpit,
// twin engine nozzles with emissive glow). Moves along x only (classic).
// Respawn invulnerability blinks the hull and dims the engines.

import * as THREE from 'three';
import { clamp } from '../../shared/utils/Math.js';
import { CONFIG } from '../config.js';

export default class Player {
  constructor(scene) {
    this.scene = scene;
    this.x = 0;
    this.y = CONFIG.world.playerY;
    this.radius = CONFIG.player.radius;
    this.alive = true;
    this.invulnerable = 0; // seconds of respawn invulnerability remaining
    this.fireCooldown = 0;

    this.group = new THREE.Group();
    this.group.position.set(this.x, this.y, 0);

    const hullMat = new THREE.MeshStandardMaterial({
      color: 0x0a1626,
      metalness: 0.85,
      roughness: 0.32,
      emissive: 0x00f0ff,
      emissiveIntensity: 0.12,
    });
    const glowMat = new THREE.MeshStandardMaterial({
      color: 0x000000,
      emissive: 0x00f0ff,
      emissiveIntensity: 2.6,
      roughness: 0.5,
      metalness: 0.0,
    });
    const coreMat = new THREE.MeshStandardMaterial({
      color: 0x000000,
      emissive: 0x7df9ff,
      emissiveIntensity: 3.2,
      roughness: 0.4,
      metalness: 0.0,
    });

    // Hull: a flattened tetrahedron reads as a retro cannon from the front.
    const hull = new THREE.Mesh(new THREE.ConeGeometry(0.52, 1.05, 4), hullMat);
    hull.rotation.x = Math.PI / 2; // point +z toward camera
    hull.rotation.z = Math.PI / 4;
    hull.scale.set(1.25, 0.8, 0.55);
    this.group.add(hull);

    // Cockpit fin.
    const fin = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.5, 0.34), coreMat);
    fin.position.set(0, 0.34, -0.05);
    this.group.add(fin);

    // Twin engine nozzles (emissive) behind the hull.
    const nozzleGeo = new THREE.CylinderGeometry(0.13, 0.17, 0.3, 12);
    for (const side of [-1, 1]) {
      const n = new THREE.Mesh(nozzleGeo, glowMat);
      n.rotation.x = Math.PI / 2;
      n.position.set(side * 0.42, -0.28, -0.28);
      this.group.add(n);
    }

    scene.add(this.group);
    this._hullMat = hullMat;
    this._glowMat = glowMat;
    this._coreMat = coreMat;
  }

  /** True if the cooldown has elapsed and the player can shoot. */
  canFire() {
    return this.alive && this.fireCooldown <= 0;
  }

  /** Arm the cooldown (call after a successful shot). */
  armFire() {
    this.fireCooldown = CONFIG.player.fireCooldown;
  }

  update(dt) {
    if (this.invulnerable > 0) this.invulnerable = Math.max(0, this.invulnerable - dt);
    if (this.fireCooldown > 0) this.fireCooldown = Math.max(0, this.fireCooldown - dt);
  }

  /** Move by a normalized axis in [-1, 1]. */
  move(dt, axis) {
    if (!this.alive) return;
    this.x = clamp(this.x + axis * CONFIG.world.playerSpeed * dt, -CONFIG.world.playerHalfRange, CONFIG.world.playerHalfRange);
    this.group.position.x = this.x;
    // Subtle bank into the direction of travel.
    this.group.rotation.z = -axis * 0.22;
  }

  /** Invulnerability blink: hull + engine glow pulse. */
  _applyBlink() {
    if (this.invulnerable > 0) {
      const on = Math.sin(performance.now() * 0.03) > 0;
      const k = on ? 1.0 : 0.25;
      this._hullMat.emissiveIntensity = 0.12 * k;
      this._glowMat.emissiveIntensity = 2.6 * k;
      this._coreMat.emissiveIntensity = 3.2 * k;
    } else {
      this._hullMat.emissiveIntensity = 0.12;
      this._glowMat.emissiveIntensity = 2.6;
      this._coreMat.emissiveIntensity = 3.2;
    }
  }

  /** Called when the player is destroyed. */
  die() {
    this.alive = false;
    this.group.visible = false;
  }

  /** Called after the death delay, if lives remain. */
  respawn() {
    this.alive = true;
    this.x = 0;
    this.invulnerable = CONFIG.player.respawnInvuln;
    this.fireCooldown = 0;
    this.group.visible = true;
    this.group.position.set(this.x, this.y, 0);
    this.group.rotation.z = 0;
  }

  dispose() {
    this.scene.remove(this.group);
    for (const child of this.group.children) {
      if (child.geometry) child.geometry.dispose();
    }
    this._hullMat.dispose();
    this._glowMat.dispose();
    this._coreMat.dispose();
    this.group.children.length = 0;
  }
}

// Space_Invaders/entities/Bullet.js — player bullet (pooled).
// Swept segment vs circle collision is done by the game (CollisionSystem);
// this class owns motion + visuals.

import * as THREE from 'three';
import { CONFIG } from '../config.js';

const C = CONFIG.bullet;

export default class Bullet {
  constructor(scene) {
    this.scene = scene;
    this.active = false;
    this.x = 0;
    this.y = 0;
    this.z = 0;
    this.px = 0; // previous position (for swept test)
    this.py = 0;
    this.vy = C.speed;
    this.radius = C.radius;

    const geo = new THREE.CapsuleGeometry(0.09, 0.34, 3, 8);
    const mat = new THREE.MeshStandardMaterial({
      color: 0x06202a,
      emissive: 0x7df9ff,
      emissiveIntensity: 3.2,
      roughness: 0.3,
      metalness: 0.1,
    });
    this.mesh = new THREE.Mesh(geo, mat);
    this.mesh.visible = false;
    this.mesh.renderOrder = 12;
    scene.add(this.mesh);
  }

  spawn(x, y) {
    this.active = true;
    this.x = x;
    this.y = y;
    this.z = 0;
    this.px = x;
    this.py = y;
    this.mesh.visible = true;
    this.mesh.position.set(x, y, 0);
  }

  update(dt) {
    if (!this.active) return;
    this.px = this.x;
    this.py = this.y;
    this.y += this.vy * dt;
    this.mesh.position.set(this.x, this.y, this.z);
  }

  deactivate() {
    this.active = false;
    this.mesh.visible = false;
  }

  /** Mark as consumed (hit something). The game releases it to the pool. */
  kill() {
    this.active = false;
    this.mesh.visible = false;
  }

  dispose() {
    this.scene.remove(this.mesh);
    this.mesh.geometry.dispose();
    this.mesh.material.dispose();
  }
}

